import React from 'react';
import { Line, Bar } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    BarElement,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';
import annotationPlugin from 'chartjs-plugin-annotation';

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    BarElement,
    Title,
    Tooltip,
    Legend,
    annotationPlugin
);

const StockChart = ({ chartData, historicalIndicators }) => {
    const livePriceData = {
        labels: chartData.labels,
        datasets: [
            {
                label: 'Live Stock Price',
                data: chartData.values,
                fill: false,
                borderColor: 'rgb(75, 192, 192)',
                backgroundColor: 'rgba(75, 192, 192, 0.5)',
                pointRadius: 1,
            },
        ],
    };

    const livePriceOptions = {
        responsive: true,
        plugins: { title: { display: true, text: 'Live Price (1-Minute Updates)' } },
        scales: { y: { title: { display: true, text: 'Price' } } },
    };

    if (!historicalIndicators) {
        return (
            <div>
                <Line data={livePriceData} options={livePriceOptions} />
            </div>
        );
    }

    const { labels, close, rsi, macd, macds, macdh, bb_upper, bb_middle, bb_lower, stoch_k, stoch_d } = historicalIndicators;

    // Chart 2: Bollinger Bands (daily)
    const bollingerChartData = {
        labels,
        datasets: [
            { label: 'Daily Close', data: close, borderColor: 'rgba(200, 200, 200, 0.5)', pointRadius: 0 },
            { label: 'Upper Band', data: bb_upper, borderColor: 'rgb(153, 102, 255)', pointRadius: 0 },
            { label: 'Middle Band', data: bb_middle, borderColor: 'rgb(201, 203, 207)', pointRadius: 0 },
            { label: 'Lower Band', data: bb_lower, borderColor: 'rgb(153, 102, 255)', pointRadius: 0 },
        ],
    };
    const bollingerChartOptions = { responsive: true, plugins: { title: { display: true, text: 'Bollinger Bands (Daily)' } } };

    // Chart 3: RSI (daily)
    const rsiChartData = {
        labels,
        datasets: [{ label: 'RSI', data: rsi, borderColor: 'rgb(255, 99, 132)', pointRadius: 0 }],
    };
    const rsiChartOptions = { responsive: true, plugins: { title: { display: true, text: 'RSI (Daily)' } }, scales: { y: { min: 0, max: 100 } } };

    // Chart 4: MACD (daily)
    const macdChartData = {
        labels,
        datasets: [
            { type: 'line', label: 'MACD', data: macd, borderColor: 'rgb(54, 162, 235)', pointRadius: 0 },
            { type: 'line', label: 'Signal', data: macds, borderColor: 'rgb(255, 206, 86)', pointRadius: 0 },
            { type: 'bar', label: 'Histogram', data: macdh, backgroundColor: 'rgba(169, 169, 169, 0.5)' },
        ],
    };
    const macdChartOptions = { responsive: true, plugins: { title: { display: true, text: 'MACD (Daily)' } } };

    // Chart 5: Stochastic Oscillator (daily)
    const stochChartData = {
        labels,
        datasets: [
            { label: '%K', data: stoch_k, borderColor: 'rgb(0, 255, 0)', pointRadius: 0 },
            { label: '%D', data: stoch_d, borderColor: 'rgb(255, 165, 0)', pointRadius: 0 },
        ],
    };
    const stochChartOptions = { responsive: true, plugins: { title: { display: true, text: 'Stochastic Oscillator (Daily)' } }, scales: { y: { min: 0, max: 100 } } };

    return (
        <div>
            <div style={{ marginBottom: '20px' }}>
                <Line data={livePriceData} options={livePriceOptions} />
            </div>
            <div style={{ marginBottom: '20px' }}>
                <Line data={bollingerChartData} options={bollingerChartOptions} />
            </div>
            <div style={{ marginBottom: '20px' }}>
                <Line data={rsiChartData} options={rsiChartOptions} />
            </div>
            <div style={{ marginBottom: '20px' }}>
                <Line data={macdChartData} options={macdChartOptions} />
            </div>
            <div style={{ marginBottom: '20px' }}>
                <Line data={stochChartData} options={stochChartOptions} />
            </div>
        </div>
    );
};

export default StockChart;
